456	                .enumerate()
457	                .map(|(index, row)| {
458	                    Line::from(vec![
459	                        Span::styled(format!("{:>4} ", index + 1), muted),
460	                        Span::styled(expand_tabs(row).into_owned(), Style::default().fg(Color::White)),
461	                    ])
462	                })
463	                .collect::<Vec<_>>(),
464	        ),
465	        None => (format!("Paste #{number}"), vec![Line::from(Span::styled("This paste is no longer in the draft.", muted))]),
