467	    let block = Block::default()
468	        .borders(Borders::ALL)
469	        .border_type(BorderType::Rounded)
470	        .border_style(Style::default().fg(ACCENT))
471	        .title(Span::styled(format!(" {title} "), Style::default().fg(ACCENT).add_modifier(Modifier::BOLD)))
472	        .title_bottom(key_hints(&[("esc", "close"), ("↑↓", "scroll"), ("ctrl+x", "edit inline")]));
473	    let inner = block.inner(rect);
474	    frame.render_widget(Clear, rect);
475	    frame.render_widget(block, rect);
476	    scroll_body(frame, inner, lines, scroll)
477	}
