fn n_denies_at_once() {
    let (mut state, t0) = panel(1000);
    assert_eq!(state.on_key_at(key(KeyCode::Char('n')), at(t0, 2700)), deny("approval-1"));
    assert!(matches!(state.transcript.last(), Some(Entry::Decision { verdict: Verdict::Denied, .. })));

